def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "open_jar_unsafe": And([
            Not(self.jar_stabilized),
            self.jar_is_glass,
            self.jar_is_heavy,
            self.robot_has_two_manipulators,
            self.non_slip_mat_available
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
